INSERT INTO SMS_RECEIVER ( 
	IDX, USER_NAME, MOBILE, SMS_GROUP_ID, MEMO 
) VALUES ( (SELECT IFNULL( MAX(IDX) + 1, 1 ) AS idx
		FROM SMS_RECEIVER AS ALIAS_FOR_SUBQUERY), #{user_name} 
	, HEX(AES_ENCRYPT(#{mobile}, MD5(#{organ_code}))), #{sms_group_id}, #{memo}
)

